def lore_context(message: str, character: str = "") -> str:
    """Select topic notes to keep prompt relevant and within context limits."""
    text = (message + " " + character).casefold()
    selected = ["cosmology"]
    keywords = {
        "lamps_trees": ("درخت", "چراغ", "تلپریون", "لائورلین", "ستاره", "خورشید", "ماه", "والینور"),
        "silmarils": ("سیلماریل", "فئانور", "نولدور", "سوگند", "مورگوث", "ملکور", "فینوه"),
        "first_age": ("دوران اول", "بلریاند", "برن", "لوتین", "تورین", "ائارندیل", "گوندولین", "دوریات"),
        "second_age": ("دوران دوم", "نومه‌نور", "نومِنور", "حلقه", "کلبریمبور", "الندیل", "ایسیلدور", "آناتار"),
        "third_age": ("دوران سوم", "هابیت", "گندالف", "فرودو", "آراگورن", "گالوم", "سائورون", "یاران حلقه", "اسماگ"),
        "peoples": ("الف", "دورف", "هابیت", "انسان", "اورک", "مایار", "والار", "اِنت", "نژاد", "زبان"),
        "characters": ("کیست", "شخصیت", "رابطه", "پسر", "دختر", "همسر", "پدر", "مادر", "برادر", "خواهر"),
        "places": ("کجا", "مکان", "سرزمین", "شهر", "دژ", "کوه", "موردور", "ریوندل", "گوندور", "شایر"),
        "languages": ("تلفظ", "چطور می‌گن", "کوئنیا", "سیندارین", "خوزدول", "زبان", "املای", "نام"),
    }
    for section, terms in keywords.items():
        if any(term in text for term in terms):
            selected.append(section)
    # محدودیت امن برای جلوگیری از بزرگ‌شدن بی‌رویهٔ system prompt
    return "\n\n".join(LORE[key] for key in dict.fromkeys(selected))
